  s+=arrow(ox,oy,ox+L,oy,'--fg',2.4)+S.t(ox+L+4,oy+5,'Vph','','start');
  s+=`<path d="M${fx(ex)} ${fx(ey)}V${oy}M${fx(ex)} ${fx(ey)}H${ox}" stroke="var(--muted)" stroke-dasharray="4 3" fill="none"/>`;
  s+=arrow(ox,oy,ex,oy,'--blue',3)+S.t((ox+ex)/2+6,oy-8,'Ic','b');
